type Data=Record<string,unknown>;type Account={id:string;name:string;type:string;group?:string;currentBalance:number;openingBalance:number;isActive:boolean;description?:string;_count?:{transactions:number};transactions?:Transaction[]};type Category={id:string;name:string;nameBangla?:string;description?:string;parentId?:string|null};type Transaction={id:string;txnId?:string;accountId:string;account?:{id?:string;name:string;type:string;currentBalance?:number};amount:number;flowType:string;txnType:string;paymentMethod?:string;note?:string;createdAt:string;accountBalanceBefore?:number;accountBalanceNow?:number;sale?:Data|null;purchase?:Data|null;expense?:Data|null;income?:Data|null};type Entry={id:string;amount:number;date:string;note?:string;category?:{name:string};subCategory?:{name:string};account?:{name:string;type?:string};branch?:{name:string};recordedBy?:{fullName?:string;username?:string};transactions?:Transaction[];incomeNumber?:string;expenseNumber?:string};type View=FinanceView;
function descendantCategoryIds(items:Category[],rootId:string|null){const result=new Set<string>(rootId?[rootId]:[]);let changed=true;while(changed){changed=false;for(const item of items)if(item.parentId&&result.has(item.parentId)&&!result.has(item.id)){result.add(item.id);changed=true;}}return result;}
function rows<T>(v:unknown):T[]{if(Array.isArray(v))return v as T[];if(v&&typeof v==="object"){const o=v as Data;if("data"in o)return rows<T>(o.data);for(const k of ["accounts","transactions","incomes","expenses","categories"])if(k in o)return rows<T>(o[k]);}return[];}
