 {view==="accounts"&&<div className="finance-metrics"><div><span className="sales-metric-icon green"><Wallet size={16}/></span><small>{t("Accounts on this page")}</small><strong>{loading ? "—" : totals.count}</strong></div><div><span className="sales-metric-icon blue"><Banknote size={16}/></span><small>{t("Current balances · page")}</small><strong>{loading ? "—" : taka(totals.balance)}</strong></div><div><span className="sales-metric-icon amber"><ArrowDownLeft size={16}/></span><small>{t("Cash account balance · page")}</small><strong>{loading ? "—" : taka(totals.cash)}</strong></div></div>}
